  unfold Cc_1RB1LA_0LA1RC_1RD0LB_1LC0RB, cden, Z0_1RB1LA_0LA1RC_1RD0LB_1LC0RB, Z1_1RB1LA_0LA1RC_1RD0LB_1LC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_0LA1RC_1RD0LB_1LC0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB1LA_0LA1RC_1RD0LB_1LC0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_1RB1LA_0LA1RC_1RD0LB_1LC0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LA1RC_1RD0LB_1LC0RB, cden, P0_1RB1LA_0LA1RC_1RD0LB_1LC0RB, P1_1RB1LA_0LA1RC_1RD0LB_1LC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
