    exists (8 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LA1RC_1RD0LB_1LC0RB P0_1RB1LA_0LA1RC_1RD0LB_1LC0RB P1_1RB1LA_0LA1RC_1RD0LB_1LC0RB 8 10
