Lemma geo_1RB1LA_0LA1RC_1RD0LB_1LC0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_1RD0LB_1LC0RB) = lift (Cc (Pos.succ p)).
