(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_1RD0LB_1LC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
