    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_1RD0RB_0LD0LA [SWinR 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_1RD0RB_0LD0LA : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_1RD0RB_0LD0LA.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_1RD0RB_0LD0LA pins_1RB1LA_0LA1RC_1RD0RB_0LD0LA Cc 1).
