  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_1RD1RD_0LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_1RD1RD_0LA0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0LA1RC_1RD1RD_0LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LA1RC_1RD1RD_0LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0LA1RC_1RD1RD_0LA0RB t p (pow2 j)).
  - exists (6 * j + 5), (cden [] [] j BB1_1RB1LA_0LA1RC_1RD1RD_0LA0RB). split;
      [| exact (gbo_1RB1LA_0LA1RC_1RD1RD_0LA0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_1RD1RD_0LA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_1RD1RD_0LA0RB B0_1RB1LA_0LA1RC_1RD1RD_0LA0RB BB1_1RB1LA_0LA1RC_1RD1RD_0LA0RB 6 5
             run_boot_1RB1LA_0LA1RC_1RD1RD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
