    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LB1RC_1LA0RD_0RB1LD B0_1RB1LA_0LB1RC_1LA0RD_0RB1LD B1_1RB1LA_0LB1RC_1LA0RD_0RB1LD 6 9 p j' [] []).
    + exact run_ovf_1RB1LA_0LB1RC_1LA0RD_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LB1RC_1LA0RD_0RB1LD p j' E).
    + exact (geo_1RB1LA_0LB1RC_1LA0RD_0RB1LD p j' E).
    + lia.
