Lemma fireo_1RB1LA_0LB1RC_1LA0RD_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LB1RC_1LA0RD_0RB1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LB1RC_1LA0RD_0RB1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LB1RC_1LA0RD_0RB1LD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
