  unfold Cin_1RB1LA_0LB1RC_1LA1RD_0LD0RB, cden, AI0_1RB1LA_0LB1RC_1LA1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0LB1RC_1LA1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB1LA_0LB1RC_1LA1RD_0LD0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_0LB1RC_1LA1RD_0LD0RB, cden, AI1_1RB1LA_0LB1RC_1LA1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_0LB1RC_1LA1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB1LA_0LB1RC_1LA1RD_0LD0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_0LB1RC_1LA1RD_0LD0RB v i q0 E)].
  rewrite (gsn_1RB1LA_0LB1RC_1LA1RD_0LD0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LB1RC_1LA1RD_0LD0RB AI0_1RB1LA_0LB1RC_1LA1RD_0LD0RB AI1_1RB1LA_0LB1RC_1LA1RD_0LD0RB 6 10
           run_inner_1RB1LA_0LB1RC_1LA1RD_0LD0RB (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
