    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 6; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 6; SCycR 3; SWin 2; SRotL 1; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 5]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_0LB1RC_1RD1RD_0LA0RB
