Definition chn_1RB1LA_0LC0RA_0RA0LD_1RA1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LA_0LC0RA_0RA0LD_1RA1LC : srun tm false true chn_1RB1LA_0LC0RA_0RA0LD_1RA1LC AI0_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Some (AI1_1RB1LA_0LC0RA_0RA0LD_1RA1LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LA_0LC0RA_0RA0LD_1RA1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1LA_0LC0RA_0RA0LD_1RA1LC : srun tm true true chb_1RB1LA_0LC0RA_0RA0LD_1RA1LC B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Some (BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_0LC0RA_0RA0LD_1RA1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1LA_0LC0RA_0RA0LD_1RA1LC : srun tm true true che_1RB1LA_0LC0RA_0RA0LD_1RA1LC BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Some (B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, A0_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Ip q0 ++ [S0]) [] j A1_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, A1_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LA_0LC0RA_0RA0LD_1RA1LC A0_1RB1LA_0LC0RA_0RA0LD_1RA1LC A1_1RB1LA_0LC0RA_0RA0LD_1RA1LC 4 4
             run_int_1RB1LA_0LC0RA_0RA0LD_1RA1LC (Ip q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j q0 E).
Qed.

Lemma gso_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC
             = (StB, (rep [S1;S0] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_0LC0RA_0RA0LD_1RA1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_0LC0RA_0RA0LD_1RA1LC. reflexivity.
Qed.

Lemma gsn_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, AI0_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LC0RA_0RA0LD_1RA1LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, AI1_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LC0RA_0RA0LD_1RA1LC).
  split; [lia|]. split; [| exact (gen_1RB1LA_0LC0RA_0RA0LD_1RA1LC v i q0 E)].
  rewrite (gsn_1RB1LA_0LC0RA_0RA0LD_1RA1LC v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LC0RA_0RA0LD_1RA1LC AI0_1RB1LA_0LC0RA_0RA0LD_1RA1LC AI1_1RB1LA_0LC0RA_0RA0LD_1RA1LC 4 4
           run_inner_1RB1LA_0LC0RA_0RA0LD_1RA1LC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall j, lift (cden [] [] j BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0LC0RA_0RA0LD_1RA1LC. rewrite epow2_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LC0RA_0RA0LD_1RA1LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LC0RA_0RA0LD_1RA1LC, cden, BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LC0RA_0RA0LD_1RA1LC p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC0RA_0RA0LD_1RA1LC j)].
    rewrite (gso_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC0RA_0RA0LD_1RA1LC B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC 4 4
             run_boot_1RB1LA_0LC0RA_0RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 8), (cden [] [] j B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC).
    split; [| exact (geo_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j E)].
    rewrite (gxi_1RB1LA_0LC0RA_0RA0LD_1RA1LC j).
    exact (srun_sound tm true true che_1RB1LA_0LC0RA_0RA0LD_1RA1LC BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC B1_1RB1LA_0LC0RA_0RA0LD_1RA1LC 4 8
             run_exit_1RB1LA_0LC0RA_0RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LC0RA_0RA0LD_1RA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0LC0RA_0RA0LD_1RA1LC t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC). split;
      [| exact (gbo_1RB1LA_0LC0RA_0RA0LD_1RA1LC j)].
    rewrite (gso_1RB1LA_0LC0RA_0RA0LD_1RA1LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC0RA_0RA0LD_1RA1LC B0_1RB1LA_0LC0RA_0RA0LD_1RA1LC BB1_1RB1LA_0LC0RA_0RA0LD_1RA1LC 4 4
             run_boot_1RB1LA_0LC0RA_0RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0LC0RA_0RA0LD_1RA1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0LC0RA_0RA0LD_1RA1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LC0RA_0RA0LD_1RA1LC : forall t, ~ In t pins_1RB1LA_0LC0RA_0RA0LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LC0RA_0RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RA_0RA0LD_1RA1LC (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC0RA_0RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LC0RA_0RA0LD_1RA1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RA_0RA0LD_1RA1LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC0RA_0RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RA_0RA0LD_1RA1LC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC0RA_0RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LC0RA_0RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_0LC0RA_0RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RA_0RA0LD_1RA1LC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC0RA_0RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LC0RA_0RA0LD_1RA1LC : NeverQuasiHaltsTr tm_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LC0RA_0RA0LD_1RA1LC pins_1RB1LA_0LC0RA_0RA0LD_1RA1LC Cc 1).
  - exact boot_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
  - intros p _. apply lap_1RB1LA_0LC0RA_0RA0LD_1RA1LC.
  - intros t Ht p _. apply fire_1RB1LA_0LC0RA_0RA0LD_1RA1LC. exact Ht.
Qed.

