  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LC0RA_1RA0LD_1RA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LC0RA_1RA0LD_1RA1LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LA_0LC0RA_1RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_0LC0RA_1RA0LD_1RA1LC = Some t ->
