      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SWinL 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LC0RA_1RA0LD_1RA1LC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LC0RA_1RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LA_0LC0RA_1RA0LD_1RA1LC : NeverQuasiHaltsTr tm_1RB1LA_0LC0RA_1RA0LD_1RA1LC.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LC0RA_1RA0LD_1RA1LC pins_1RB1LA_0LC0RA_1RA0LD_1RA1LC Cc 1).
