    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RB_0RA0LD_1RA1LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC0RB_0RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC0RB_0RA0LD_1RA1LC (StC, S0)).
    intros p1 j1 E1.
