Lemma fireo_1RB1LA_0LC0RB_1LD1LC_0RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LC0RB_1LD1LC_0RA1LC = Some t ->
