(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_0LC0RB_1RA0LD_1LA1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1LA_0LC0RB_1RA0LD_1LA1LD /\
