(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_0LC0RD_1LA0LC_1RA0RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1LA_0LC0RD_1LA0LC_1RA0RD /\
