Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LC1RB_1RA1LD_1LC0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LC1RB_1RA1LD_1LC0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LC1RB_1RA1LD_1LC0RB
             = (StB, (rep [S1;S1] (S j) ++ [S1;S1], S0, []))).
