  split; [lia|]. split; [| exact (gen_1RB1LA_0LC1RB_1RA1LD_1LC0RB v i q0 E)].
  rewrite (gsn_1RB1LA_0LC1RB_1RA1LD_1LC0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LC1RB_1RA1LD_1LC0RB AI0_1RB1LA_0LC1RB_1RA1LD_1LC0RB AI1_1RB1LA_0LC1RB_1RA1LD_1LC0RB 4 4
           run_inner_1RB1LA_0LC1RB_1RA1LD_1LC0RB (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 2/0
    trailing blanks. *)
Lemma gbo_1RB1LA_0LC1RB_1RA1LD_1LC0RB : forall j, lift (cden [] [] j BB1_1RB1LA_0LC1RB_1RA1LD_1LC0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LC1RB_1RA1LD_1LC0RB = (StB, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB1LA_0LC1RB_1RA1LD_1LC0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
