  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB1LA_0LC1RB_1RA1LD_1LC0RB. rewrite epow2_1RB1LA_0LC1RB_1RA1LD_1LC0RB.
