(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LC1RB_1RA1LD_1LC0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_0LC1RB_1RA1LD_1LC0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LC1RB_1RA1LD_1LC0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LC1RB_1RA1LD_1LC0RB p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LA_0LC1RB_1RA1LD_1LC0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC1RB_1RA1LD_1LC0RB j)].
    rewrite (gso_1RB1LA_0LC1RB_1RA1LD_1LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC1RB_1RA1LD_1LC0RB B0_1RB1LA_0LC1RB_1RA1LD_1LC0RB BB1_1RB1LA_0LC1RB_1RA1LD_1LC0RB 4 4
             run_boot_1RB1LA_0LC1RB_1RA1LD_1LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_1RB1LA_0LC1RB_1RA1LD_1LC0RB).
    split; [| exact (geo_1RB1LA_0LC1RB_1RA1LD_1LC0RB p j E)].
    rewrite (gxi_1RB1LA_0LC1RB_1RA1LD_1LC0RB j).
    exact (srun_sound tm true true che_1RB1LA_0LC1RB_1RA1LD_1LC0RB BE0_1RB1LA_0LC1RB_1RA1LD_1LC0RB B1_1RB1LA_0LC1RB_1RA1LD_1LC0RB 4 10
             run_exit_1RB1LA_0LC1RB_1RA1LD_1LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LA_0LC1RB_1RA1LD_1LC0RB : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LA_0LC1RB_1RA1LD_1LC0RB = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LA_0LC1RB_1RA1LD_1LC0RB q p (pow2 j)).
