Lemma fire_1RB1LA_0LC1RC_0RD1RD_0LA0RB : forall t, ~ In t pins_1RB1LA_0LC1RC_0RD1RD_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
