  exists (4 * j + 12), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_0LC1RC_1LD0RB_1RA1LD).
  split; [lia|]. split; [| exact (gei_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j q0 E)].
  rewrite (gsi_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j q0 E).
