Lemma lbl_1RB1LA_0LC1RC_1LD0RB_1RA1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LC1RC_1LD0RB_1RA1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LC1RC_1LD0RB_1RA1LD) = lift (Cc (Pos.succ p)).
