(** ** The lap *)

Lemma lap_1RB1LA_0LC1RC_1LD0RB_1RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LC1RC_1LD0RB_1RA1LD B0_1RB1LA_0LC1RC_1LD0RB_1RA1LD B1_1RB1LA_0LC1RC_1LD0RB_1RA1LD 4 13 p j' [] []).
    + exact run_ovf_1RB1LA_0LC1RC_1LD0RB_1RA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j' E).
    + exact (geo_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LC1RC_1LD0RB_1RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 26.
  assert (H : match csteps tm 26 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 26 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LC1RC_1LD0RB_1RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LC1RC_1LD0RB_1RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LC1RC_1LD0RB_1RA1LD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
