(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LC1RC_1RB1RD_0LA0RB : forall t, ~ In t pins_1RB1LA_0LC1RC_1RB1RD_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LC1RC_1RB1RD_0LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 3; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 3; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_0LC1RC_1RB1RD_0LA0RB
      with (l := [SRotL 1; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LC1RC_1RB1RD_0LA0RB (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LC1RC_1RB1RD_0LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LC1RC_1RB1RD_0LA0RB : NeverQuasiHaltsTr tm_1RB1LA_0LC1RC_1RB1RD_0LA0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LC1RC_1RB1RD_0LA0RB pins_1RB1LA_0LC1RC_1RB1RD_0LA0RB Cc 1).
  - exact boot_1RB1LA_0LC1RC_1RB1RD_0LA0RB.
