Lemma gei_1RB1LA_0LC1RD_0LA1LA_1RB0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_0LC1RD_0LA1LA_1RB0RB) = lift (Cc (Pos.succ p)).
Proof.
