(** The chain into this family lands on its anchor up to 0/3
    trailing blanks. *)
Lemma gbo_1RB1LA_0LC1RD_0LC1LA_1LC0RB : forall j, lift (cden [] [] j BB1_1RB1LA_0LC1RD_0LC1LA_1LC0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LC1RD_0LC1LA_1LC0RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ((([S1]) ++ [S0]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0LC1RD_0LC1LA_1LC0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, [S1]))).
  { unfold Cin_1RB1LA_0LC1RD_0LC1LA_1LC0RB. rewrite epow2_1RB1LA_0LC1RD_0LC1LA_1LC0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LC1RD_0LC1LA_1LC0RB. rewrite ?lift_app_blank. reflexivity.
